def transform(grid):
    # Recolor components that form one of the repeatedly demonstrated spatial motifs.
    g=[row[:] for row in grid]
    R,C=len(g),len(g[0])
    seen=set()
    comps=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]!=2 or (r,c) in seen: continue
            stack=[(r,c)];seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop();cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    q=(y+dy,x+dx)
                    if 0<=q[0]<R and 0<=q[1]<C and g[q[0]][q[1]]==2 and q not in seen:
                        seen.add(q);stack.append(q)
            comps.append(cells)
    # Color square objects in groups with at least one neighbor in same row or column.
    boxes=[]
    for cells in comps:
        ys=[y for y,x in cells];xs=[x for y,x in cells]
        boxes.append((min(ys),min(xs),max(ys),max(xs),cells))
    for i,a in enumerate(boxes):
        y,x,Y,X,_=a
        for b in boxes[i+1:]:
            yy,xx,YY,XX,_=b
            if y==yy or x==xx:
                for cy,cx in a[4]+b[4]: g[cy][cx]=8
    return g
